{
  "sceneId": "s-001",
  "claims": [
    {
      "entity": "loc-chapel",
      "attribute": "contains_object",
      "value": "obj-amber-lantern",
      "quote": "The Amber Lantern swung close enough for its honeyed light to pick out the lines of her hands."
    },
    {
      "entity": "loc-chapel",
      "attribute": "contains_object",
      "value": "obj-binding-bell",
      "quote": "Behind her, the bronze of the Bell sat on its velvet cushion, mute and waiting."
    },
    {
      "entity": "loc-chapel",
      "attribute": "is_scene_of",
      "value": "s-001",
      "quote": "As the girls were guided from the Chapel toward the dormitory, the Headmistress’s words followed them—an instruction dressed as mercy."
    },
    {
      "entity": "group-hundred",
      "attribute": "intake_count",
      "value": "100",
      "quote": "\"This year we admit one hundred. The Folio will record names, ages, dates, provenance, and signatures."
    },
    {
      "entity": "obj-contract-folio",
      "attribute": "entry_template",
      "value": "Folio Entry— Name: __________________; Age: __; Date: ______; Intake: One hundred; Provenance (sold/placed/orphaned): __________; Signature: __________________; Witness: Headmistress / Scribe.",
      "quote": "A scribe stepped forward with the Contract Folio under his arm, a slab of leather bound like an anchor. He opened to a fresh page and read, aloud, the form as he set his pen: \"Folio Entry— Name: __________________; Age: __; Date: ______; Intake: One hundred; Provenance (sold/placed/orphaned): __________; Signature: __________________; Witness: Headmistress / Scribe.\""
    },
    {
      "entity": "char-rue",
      "attribute": "age_at_entry",
      "value": "18",
      "quote": "The scribe's voice marked each line as he copied: \"Name: Rue. Age: 18. Date: this day. Intake: One hundred. Provenance: Sold by consent.\""
    },
    {
      "entity": "char-rue",
      "attribute": "location_at_end",
      "value": "loc-dormitory",
      "quote": "As the girls were guided from the Chapel toward the dormitory, the Headmistress’s words followed them—an instruction dressed as mercy."
    },
    {
      "entity": "char-headmistress",
      "attribute": "speech_contains",
      "value": "Mercy is accounted for by service and attention, not by indulgence.",
      "quote": "\"So entered under the charge of the Mercy Academy. Let the Folio stand as record and law. Let those within this house remember that mercy is accounted for by service and attention, not by indulgence.\""
    },
    {
      "entity": "char-rue",
      "attribute": "provenance_of_entry",
      "value": "Sold by consent",
      "quote": "The scribe's voice marked each line as he copied: \"Name: Rue. Age: 18. Date: this day. Intake: One hundred. Provenance: Sold by consent.\""
    },
    {
      "entity": "obj-binding-bell",
      "attribute": "used_in_scene",
      "value": "s-001",
      "quote": "Then the Bronze Bell was lifted and struck. The sound rolled through the stone like the closing of a gate."
    },
    {
      "entity": "obj-amber-lantern",
      "attribute": "used_in_scene",
      "value": "s-001",
      "quote": "A young warden, pale at the mouth with the weight of his responsibility, took the Amber Lantern from the steward and held it over the inscription so the light lay on her signature."
    }
  ],
  "presentEntities": [
    "char-rue",
    "char-headmistress",
    "obj-contract-folio",
    "obj-binding-bell",
    "obj-amber-lantern",
    "loc-mercy-academy",
    "group-hundred"
  ],
  "promises": [
    {
      "id": "pr-001",
      "promise": "The Folio will record names, ages, dates, provenance, and signatures.",
      "quote": "\"The Folio will record names, ages, dates, provenance, and signatures.\"",
      "dueByScene": ""
    }
  ],
  "paysOff": []
}

